<?php $section=$section??$page; $records=$records??[]; ?>
<section class="container section-top"><?php ff_heading($section,$section==='dashboard'?'Your demonstration member space, all in one place.':'Manage your university demonstration account.');ff_account_nav($section); ?>
<?php if($section==='dashboard'): ?><div class="dashboard-welcome"><div><p class="eyebrow"><?=e(t('welcome_back'))?></p><h2><?=e($user['name']??$user['display_name']??'')?></h2><p><?=e(t('A small step today. A stronger routine tomorrow.'))?></p></div><a class="button" href="<?=e(url('classes'))?>"><?=e(t('find_a_class'))?> <?=ff_icon()?></a></div><div class="stat-grid"><?php foreach($stats??[] as $key=>$value): ?><a class="stat-card" href="<?=e(url(in_array($key,['bookings','orders','passes','favorites'])?$key:'passes'))?>"><span><?=e(t($key))?></span><strong><?=e(is_scalar($value)?$value:'—')?></strong></a><?php endforeach ?></div><div class="dashboard-links"><?php foreach(['passes'=>'View and print your digital demo membership pass.','bookings'=>'See your reservations, confirmations and cancellation options.','orders'=>'Review successful, failed and pending demonstration orders.','favorites'=>'Keep the services, trainers and classes you like in one place.'] as $route=>$caption): ?><a class="panel" href="<?=e(url($route))?>"><h3><?=e(t($route))?> <?=ff_icon()?></h3><p><?=e(t($caption))?></p></a><?php endforeach ?></div>
<?php elseif($section==='favorites'): ?><div class="card-grid three"><?php foreach($records as $item): ?><div><?php ff_card($item); ?><div class="favorite-control"><?php ff_favorite($item,true); ?></div></div><?php endforeach ?></div><?php if(!$records)ff_empty('Your favorites are waiting to be discovered.','services'); ?>
<?php elseif($section==='bookings'): ?><?php foreach($records as $booking): ?><article class="booking-record panel"><div><div class="badge-row"><?php ff_badge($booking['status']??'confirmed'); ?></div><h2><?=e($booking['title']??'')?></h2><p><?=e(local_time($booking['starts_at']??$booking['start_at']??''))?> · Europe/Skopje</p><p><?=e($booking['trainer']??'')?> · <?=e(t($booking['room']??''))?></p><p class="fine-print"><?=e(t('booking_reference'))?>: <?=e($booking['reference']??$booking['id'])?></p><?php if(($booking['session_status']??'scheduled')==='cancelled'): ?><p class="alert info"><?=e(t('The administrator has cancelled this session.'))?></p><?php endif ?><?php if(!empty($booking['change_note'])): ?><p class="alert info"><?=e($booking['change_note'])?></p><?php endif ?><?php if(!empty($booking['original_starts_at'])): ?><p class="fine-print"><?=e(t('original_date'))?>: <?=e(local_time($booking['original_starts_at']))?></p><?php endif ?><?php if(!empty($booking['updated_at'])): ?><p class="fine-print"><?=e(t('last_updated'))?>: <?=e(local_time($booking['updated_at']))?></p><?php endif ?></div><div class="record-actions"><a class="button secondary small" href="<?=e(url('class',['id'=>$booking['session_id']]))?>"><?=e(t('view_class'))?></a><button class="button secondary small" type="button" data-print><?=e(t('print_confirmation'))?></button><?php if(($booking['status']??'')==='confirmed'): ?><form method="post" data-confirm="<?=e(t('Cancel this demonstration booking?'))?>"><?=csrf_field()?><input type="hidden" name="action" value="cancel_booking"><input type="hidden" name="id" value="<?=e($booking['id'])?>"><input type="hidden" name="booking_id" value="<?=e($booking['id'])?>"><button class="button small danger" type="submit"><?=e(t('cancel_booking'))?></button></form><?php endif ?></div></article><?php endforeach ?><?php if(!$records)ff_empty('Your next class is waiting.','classes'); ?>
<?php elseif($section==='passes'): ?><div class="pass-grid"><?php foreach($records as $pass): ?><article class="digital-pass"><div class="pass-top"><span class="brand-text">FITNESS FACTORY</span><?php  ?></div><p class="eyebrow"><?=e(t('member_pass'))?></p><h2><?=e($pass['title']??$pass['plan_title']??'')?></h2><h3><?=e($user['name']??$user['display_name']??'')?></h3><dl><div><dt><?=e(t('status'))?></dt><dd><?=e(t($pass['effective_status']??$pass['status']??'pending'))?></dd></div><div><dt><?=e(t('valid_from'))?></dt><dd><?=e(local_time($pass['starts_at']??'','d M Y'))?></dd></div><div><dt><?=e(t('valid_until'))?></dt><dd><?=e(local_time($pass['ends_at']??'','d M Y'))?></dd></div><div><dt><?=e(t('pass_id'))?></dt><dd><?=e(ff_pass_reference($pass))?></dd></div><div><dt><?=e(t('order_reference'))?></dt><dd><?=e($pass['order_reference']??'')?></dd></div></dl><p class="fine-print"><?=e(t('DEMO — does not grant real gym access.'))?></p><div class="button-row"><button class="button small" type="button" data-print><?=e(t('print_pass'))?></button><?php if(!empty($pass['token'])): ?><a class="button small outline-light" href="<?=e(url('verify',['token'=>$pass['token']]))?>"><?=e(t('verify_pass'))?></a><?php endif ?></div></article><?php endforeach ?></div><?php if(!$records)ff_empty('You do not have a demo pass yet.','memberships'); ?>
<?php elseif($section==='orders'): ?><div class="table-wrap"><table><thead><tr><?php foreach(['order_reference','date','plan','total','status','details'] as $label): ?><th scope="col"><?=e(t($label))?></th><?php endforeach ?></tr></thead><tbody><?php foreach($records as $order): ?><tr><td><?=e($order['reference']??$order['id'])?></td><td><?=e(local_time($order['created_at']??'','d M Y'))?></td><td><?=e($order['title_snapshot']??$order['title']??'')?></td><td><?=e(money($order['total']??0))?></td><td><?php ff_badge($order['status']??'pending'); ?></td><td><a class="text-link" href="<?=e(url('order',['id'=>$order['id']]))?>"><?=e(t('view_details'))?> <?=ff_icon()?></a></td></tr><?php endforeach ?></tbody></table></div><?php if(!$records)ff_empty('No demonstration orders yet.','memberships'); ?>
<?php elseif($section==='settings'): ?><div class="settings-grid"><form class="panel form-stack" method="post"><?=csrf_field()?><input type="hidden" name="action" value="profile"><h2><?=e(t('profile'))?></h2><label><span><?=e(t('name'))?></span><input name="name" value="<?=e($_POST['name']??$user['name']??$user['display_name']??'')?>" required maxlength="100" autocomplete="name"></label><label><span><?=e(t('email'))?></span><input name="email" type="email" value="<?=e($user['email']??'')?>" readonly autocomplete="email"></label><label><span><?=e(t('language'))?></span><select name="language"><?php foreach(['mk'=>'Македонски','en'=>'English','sq'=>'Shqip','de'=>'Deutsch','fr'=>'Français','it'=>'Italiano'] as $code=>$name): ?><option value="<?=$code?>" <?=($user['language']??$lang)===$code?'selected':''?>><?=e($name)?></option><?php endforeach ?></select></label><button class="button" type="submit"><?=e(t('save_profile'))?></button></form><form class="panel form-stack" method="post"><?=csrf_field()?><input type="hidden" name="action" value="password"><h2><?=e(t('change_password'))?></h2><label><span><?=e(t('current_password'))?></span><input name="current_password" type="password" autocomplete="current-password" required></label><label><span><?=e(t('new_password'))?></span><input name="new_password" type="password" autocomplete="new-password" required minlength="12" maxlength="72"></label><p class="fine-print"><?=e(t('Use at least 12 characters and no more than 72 bytes. Do not reuse an important password.'))?></p><button class="button secondary" type="submit"><?=e(t('change_password'))?></button></form><div class="panel"><h2><?=e(t('newsletter_preferences'))?></h2><p><?=e(t('Subscription preferences are stored locally by this project. No newsletter email delivery is configured.'))?></p><p><?=e(t('status'))?>: <strong><?=e(t($subscription['status']??'unsubscribed'))?></strong></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="newsletter_update"><input type="hidden" name="subscribed" value="<?=($subscription['status']??'')==='subscribed'?'0':'1'?>"><input type="hidden" name="email" value="<?=e($user['email'])?>"><?php if(($subscription['status']??'')!=='subscribed'): ?><label class="checkbox-label"><input type="checkbox" name="consent" value="1" required><span><?=e(t('I agree to store my email for the demo newsletter.'))?></span></label><?php endif ?><button class="button secondary" type="submit"><?=e(t(($subscription['status']??'')==='subscribed'?'unsubscribe':'subscribe'))?></button></form></div><div class="panel"><h2><?=e(t('session'))?></h2><p><?=e(t('Sign out when using a shared device.'))?></p><form method="post" action="<?=e(url('logout'))?>"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="button secondary" type="submit"><?=e(t('logout'))?></button></form></div></div>
<?php endif ?></section>
